@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community.</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <strong>Recipe submitted!</strong> Your recipe "<strong>@model.Title</strong>" has been added.
            <a href="/recipe/@newRecipeId">View it here</a> or <button class="btn btn-link p-0" @onclick="Reset">submit another</button>.
        </div>
    }
    else
    {
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => model.Title" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputText id="category" class="form-control" @bind-Value="model.Category" placeholder="e.g., Italian, Mexican, Desserts" />
                <ValidationMessage For="() => model.Category" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="model.Ingredients" placeholder="One ingredient per line" />
                <ValidationMessage For="() => model.Ingredients" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="8" @bind-Value="model.Steps" placeholder="Describe each step on a new line" />
                <ValidationMessage For="() => model.Steps" />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeFormModel model = new();
    private bool submitted = false;
    private int newRecipeId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };
        RecipeService.AddRecipe(recipe);
        newRecipeId = recipe.Id;
        submitted = true;
    }

    private void Reset()
    {
        model = new();
        submitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}
